    public static string Resolve(string mapId, string propertyId, string language)
    {
        if (!Texts.TryGetValue((mapId ?? "") + "/" + (propertyId ?? ""), out string[] texts))
            return string.Empty;
        int locale = AtlasBoardLocalizationLanguages.IndexOf(language);
        return texts[Math.Max(0, Math.Min(locale, texts.Length-1))];
    }
}
